INSERT INTO `app_rule_info` VALUES (42,'当触发井盖水浸事件后，上报到市政部门，等待市政部门处理完毕。','{\n    \"trigger\": {\n        \"event_type\": \"manhole-flooding\",\n        \"event_params\": {\n            \"location\": \"string\",\n            \"deviceId\": \"string\"\n        }\n    },\n    \"response\": {\n        \"chain\": [\n            {\n                \"action\": {\n                    \"action_name\": \"report_to_municipal\",\n                    \"action_params\": {\n                        \"event_type\": \"manhole-flooding\",\n                        \"location\": \"location\",\n                        \"data\": \"Flooding detected at manhole\"\n                    }\n                }\n            },\n            {\n                \"wait\": {\n                    \"action_wait\": {\n                        \"event_type\": \"manhole-flooding\",\n                        \"wait_params\": {\n                            \"deviceId\": \"deviceId\"\n                        }\n                    }\n                }\n            }\n        ]\n    }\n}','2025-11-22 16:35:13.000000',1,'manhole-flooding','[\n    {\n        \"id\": \"1a2b3c4d5e6f7g8h\",\n        \"type\": \"tab\",\n        \"label\": \"井盖积水处理流程\",\n        \"disabled\": false,\n        \"info\": \"\",\n        \"env\": []\n    },\n    {\n        \"id\": \"9i8u7y6t5r4e3w2q\",\n        \"type\": \"Event\",\n        \"z\": \"1a2b3c4d5e6f7g8h\",\n        \"event_type\": \"manhole-flooding\",\n        \"x\": 130,\n        \"y\": 160,\n        \"wires\": [\n            [\n                \"b1c2d3e4f5g6h7i8\"\n            ]\n        ]\n    },\n    {\n        \"id\": \"b1c2d3e4f5g6h7i8\",\n        \"type\": \"Action\",\n        \"z\": \"1a2b3c4d5e6f7g8h\",\n        \"action_name\": \"report_to_municipal\",\n        \"x\": 570,\n        \"y\": 160,\n        \"wires\": [\n            [\n                \"c1d2e3f4g5h6i7j8\"\n            ]\n        ]\n    },\n    {\n        \"id\": \"c1d2e3f4g5h6i7j8\",\n        \"type\": \"Wait\",\n        \"z\": \"1a2b3c4d5e6f7g8h\",\n        \"description\": \"等待工单处理完成\",\n        \"waitType\": \"action_wait\",\n        \"event_type\": \"manhole-flooding\",\n        \"waitParams\": \"deviceId\",\n        \"duration\": \"\",\n        \"unit\": null,\n        \"x\": 900,\n        \"y\": 160,\n        \"wires\": [\n            []\n        ]\n    }\n]',_binary '\0'),(43,'当触发井盖倾斜事件后，下发执法工单给附近执法人员，同时上报到市政部门，等待市政部门处理完毕。','{\n    \"trigger\": {\n        \"event_type\": \"manhole-tilte\",\n        \"event_params\": {\n            \"location\": \"string\",\n            \"deviceId\": \"string\"\n        }\n    },\n    \"response\": {\n        \"chain\": [\n            {\n                \"action\": {\n                    \"action_name\": \"issue_work_order\",\n                    \"action_params\": {\n                        \"event_type\": \"manhole-tilte\",\n                        \"location\": \"location\",\n                        \"data\": \"Manhole tilt detected\"\n                    }\n                }\n            },\n            {\n                \"action\": {\n                    \"action_name\": \"report_to_municipal\",\n                    \"action_params\": {\n                        \"event_type\": \"manhole-tilte\",\n                        \"location\": \"location\",\n                        \"data\": \"Manhole tilt reported to municipal\"\n                    }\n                }\n            },\n            {\n                \"wait\": {\n                    \"action_wait\": {\n                        \"event_type\": \"manhole-tilte\",\n                        \"wait_params\": {\n                            \"deviceId\": \"deviceId\"\n                        }\n                    }\n                }\n            }\n        ]\n    }\n}','2025-09-10 14:46:47.512015',1,'manhole-tilte','[\n    {\n        \"id\": \"e950ae3ee3f67bfa\",\n        \"type\": \"tab\",\n        \"label\": \"井盖倾斜处理流程\",\n        \"disabled\": false,\n        \"info\": \"\",\n        \"env\": []\n    },\n    {\n        \"id\": \"770b7bbd217cdc05\",\n        \"type\": \"Event\",\n        \"z\": \"e950ae3ee3f67bfa\",\n        \"event_type\": \"manhole-tilt\",\n        \"x\": 110,\n        \"y\": 260,\n        \"wires\": [\n            [\n                \"8413f09bc299bb35\"\n            ]\n        ]\n    },\n    {\n        \"id\": \"8413f09bc299bb35\",\n        \"type\": \"Action\",\n        \"z\": \"e950ae3ee3f67bfa\",\n        \"action_name\": \"issue_work_order\",\n        \"x\": 350,\n        \"y\": 260,\n        \"wires\": [\n            [\n                \"71357f9350aa1c8e\"\n            ]\n        ]\n    },\n    {\n        \"id\": \"71357f9350aa1c8e\",\n        \"type\": \"Action\",\n        \"z\": \"e950ae3ee3f67bfa\",\n        \"action_name\": \"report_to_municipal\",\n        \"x\": 610,\n        \"y\": 260,\n        \"wires\": [\n            [\n                \"7fe2df3916cbac98\"\n            ]\n        ]\n    },\n    {\n        \"id\": \"7fe2df3916cbac98\",\n        \"type\": \"Wait\",\n        \"z\": \"e950ae3ee3f67bfa\",\n        \"description\": \"等待市政处理完成\",\n        \"waitType\": \"action_wait\",\n        \"event_type\": \"manhole-tilte\",\n        \"waitParams\": \"deviceId\",\n        \"duration\": \"\",\n        \"unit\": null,\n        \"x\": 880,\n        \"y\": 260,\n        \"wires\": [\n            []\n        ]\n    }\n]',_binary '\0'),(44,'当触发机动车违章停车事件时：\n- 首先检查该区域附近是否有音箱设备（NetworkAudioNum）。如果有音箱，则：\n  - 检查该车牌号对应的车辆过去1小时内发生的违停次数。如果违停次数大于0次，则：\n    - 下发工单至相关人员进行现场处置，等待工单处理完成。\n  - 如果违停次数等于0次，则：\n    - 通过音箱广播违法停车警告，等待3分钟。\n- 如果没有音箱，则：\n  - 直接下发工单进行现场处理，等待工单处理完成。','{\n  \"trigger\": {\n    \"event_type\": \"ill_parking\",\n    \"event_params\": {\n      \"location\": \"string\",\n      \"plate_number\": \"string\"\n    }\n  },\n  \"response\": {\n    \"branch\": [\n      {\n        \"current_condition\": {\n          \"current_left\": {\n            \"type\": \"property\",\n            \"property\": \"NetworkAudioNum\"\n          },\n          \"operator\": \">\",\n          \"right\": \"0\"\n        },\n        \"chain\": [\n          {\n            \"branch\": [\n              {\n                \"history_condition\": {\n                  \"history_left\": {\n                    \"func\": \"event_count(ill_parking, 1, hour)\",\n                    \"func_params\": {\n                      \"plate_number\": \"plate_number\"\n                    }\n                  },\n                  \"operator\": \">\",\n                  \"right\": \"0\"\n                },\n                \"chain\": [\n                  {\n                    \"action\": {\n                      \"action_name\": \"issue_work_order\",\n                      \"action_params\": {\n                        \"event_type\": \"ill_parking\",\n                        \"location\": \"location\",\n                        \"data\": \"Vehicle illegal parking information\"\n                      }\n                    }\n                  },\n                  {\n                    \"wait\": {\n                      \"action_wait\": {\n                        \"event_type\": \"ill_parking\",\n                        \"wait_params\": {\n                          \"location\": \"location\"\n                        }\n                      }\n                    }\n                  }\n                ]\n              },\n              {\n                \"history_condition\": {\n                  \"history_left\": {\n                    \"func\": \"event_count(ill_parking, 1, hour)\",\n                    \"func_params\": {\n                      \"plate_number\": \"plate_number\"\n                    }\n                  },\n                  \"operator\": \"==\",\n                  \"right\": \"0\"\n                },\n                \"chain\": [\n                  {\n                    \"action\": {\n                      \"action_name\": \"broadcast\",\n                      \"action_params\": {\n                        \"event_type\": \"ill_parking\",\n                        \"location\": \"location\",\n                        \"data\": \"You have parked illegally, please leave immediately\"\n                      }\n                    }\n                  },\n                  {\n                    \"wait\": {\n                      \"time_wait\": {\n                        \"event_type\": \"ill_parking\",\n                        \"duration\": \"3\",\n                        \"unit\": \"minute\",\n                        \"wait_params\": {\n                          \"location\": \"location\"\n                        }\n                      }\n                    }\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      },\n      {\n        \"current_condition\": {\n          \"current_left\": {\n            \"type\": \"property\",\n            \"property\": \"NetworkAudioNum\"\n          },\n          \"operator\": \"==\",\n          \"right\": \"0\"\n        },\n        \"chain\": [\n          {\n            \"action\": {\n              \"action_name\": \"issue_work_order\",\n              \"action_params\": {\n                \"event_type\": \"ill_parking\",\n                \"location\": \"location\",\n                \"data\": \"Vehicle illegal parking information\"\n              }\n            }\n          },\n          {\n            \"wait\": {\n              \"action_wait\": {\n                \"event_type\": \"ill_parking\",\n                \"wait_params\": {\n                  \"location\": \"location\"\n                }\n              }\n            }\n          }\n        ]\n      }\n    ]\n  }\n}','2025-09-10 15:29:41.447015',1,'ill_parking','[\n    {\n        \"id\": \"1\",\n        \"type\": \"tab\",\n        \"label\": \"机动车违章停车处理流程\",\n        \"disabled\": false,\n        \"info\": \"\",\n        \"env\": []\n    },\n    {\n        \"id\": \"2\",\n        \"type\": \"Event\",\n        \"z