n                    {\n                        \"history_condition\": {\n                            \"history_left\": {\n                                \"func\": \"event_count(truck_dect, 1, hour)\",\n                                \"func_params\": {\n                                    \"plate_number\": \"plate_number\"\n                                }\n                            },\n                            \"operator\": \">=\",\n                            \"right\": \"3\"\n                        },\n                        \"chain\": [\n                            {\n                                \"action\": {\n                                    \"action_name\": \"issue_work_order\",\n                                    \"action_params\": {\n                                        \"event_type\": \"truck_dect\",\n                                        \"location\": \"location\",\n                                        \"data\": \"Multiple violations by the same truck\"\n                                    }\n                                }\n                            },\n                            {\n                                \"wait\": {\n                                    \"action_wait\": {\n                                        \"event_type\": \"truck_dect\",\n                                        \"wait_params\": {\n                                            \"plate_number\": \"plate_number\"\n                                        }\n                                    }\n                                }\n                            }\n                        ]\n                    }\n                ]\n            }\n        ]\n    }\n}','2025-09-22 09:29:43.338370',1,'truck_dect','[\n    {\n        \"id\": \"6e6398c8f7656013\",\n        \"type\": \"tab\",\n        \"label\": \"渣土车掉渣处理应用\",\n        \"disabled\": false,\n        \"info\": \"\",\n        \"env\": []\n    },\n    {\n        \"id\": \"6cb96cf550296f4a\",\n    