INSERT INTO `env_event` VALUES (1,'6b2b5be61c60401aa4c6da9828a7df68','manhole-flooding','井盖水浸事件，由井盖传感器检测到异常水浸状态后自动触发','{\"event_type\":\"manhole-flooding\",\"description\":\"井盖水浸事件，由井盖传感器检测到异常水浸状态后自动触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"},\"deviceId\":{\"type\":\"string\",\"description\":\"井盖传感器ID\"}}}'),(2,'6b2b5be61c60401aa4c6da9828a7df68','manhole-tilte','井盖倾斜事件，由井盖传感器监测到井盖发生位移或倾斜异常时自动触发','{\"event_type\":\"manhole-tilte\",\"description\":\"井盖倾斜事件，由井盖传感器监测到井盖发生位移或倾斜异常时自动触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"},\"deviceId\":{\"type\":\"string\",\"description\":\"井盖传感器ID\"}}}'),(3,'6b2b5be61c60401aa4c6da9828a7df68','truck_dect','渣土车识别事件，系统通过卡口摄像头识别到疑似违规或未备案的渣土车时自动触发','{\"event_type\":\"truck_dect\",\"description\":\"渣土车识别事件，系统通过卡口摄像头识别到疑似违规或未备案的渣土车时自动触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"},\"plate_number\":{\"type\":\"string\",\"description\":\"渣土车车牌号码\"}}}'),(4,'6b2b5be61c60401aa4c6da9828a7df68','ill_parking','机动车违章停车事件，系统通过视频识别技术发现机动车违停时自动触发','{\"event_type\":\"ill_parking\",\"description\":\"机动车违章停车事件，系统通过视频识别技术发现机动车违停时自动触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"},\"plate_number\":{\"type\":\"string\",\"description\":\"违章机动车车牌号\"}}}'),(5,'6b2b5be61c60401aa4c6da9828a7df68','ill_parking2','非机动车违章停车事件，系统通过视频监控识别非机动车停放在禁止区域时自动触发','{\"event_type\":\"ill_parking2\",\"description\":\"非机动车违章停车事件，系统通过视频监控识别非机动车停放在禁止区域时自动触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"}}}'),(6,'6b2b5be61c60401aa4c6da9828a7df68','waste_accumulate','垃圾堆积事件，在城市公共区域发现明显垃圾堆积时触发','{\"event_type\":\"waste_accumulate\",\"description\":\"垃圾堆积事件，在城市公共区域发现明显垃圾堆积时触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"}}}'),(7,'6b2b5be61c60401aa4c6da9828a7df68','greenbelt_stack','绿化带乱堆乱放事件，在绿化带发现杂物堆放时触发','{\"event_type\":\"greenbelt_stack\",\"description\":\"绿化带乱堆乱放事件，在绿化带发现杂物堆放时触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"}}}'),(8,'6b2b5be61c60401aa4c6da9828a7df68','road-operate','占道经营事件，商贩在公共道路摆摊行为触发','{\"event_type\":\"road-operate\",\"description\":\"占道经营事件，商贩在公共道路摆摊行为触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"}}}'),(9,'6b2b5be61c60401aa4c6da9828a7df68','out-store','店外经营事件，商户占用店外公共区域经营时触发','{\"event_type\":\"out-store\",\"description\":\"店外经营事件，商户占用店外公共区域经营时触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"}}}'),(10,'6b2b5be61c60401aa4c6da9828a7df68','road-feeding','占道饲养家禽事件，公共区域散养家禽触发','{\"event_type\":\"road-feeding\",\"description\":\"占道饲养家禽事件，公共区域散养家禽触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"}}}'),(11,'6b2b5be61c60401aa4c6da9828a7df68','trash_full','垃圾桶满溢事件，垃圾超过容量溢出时触发','{\"event_type\":\"trash_full\",\"description\":\"垃圾桶满溢事件，垃圾超过容量溢出时触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"}}}'),(12,'e730178505d54b5d98cbbd2bbc01f176','ill_parking','机动车违章停车事件，系统通过视频识别技术发现机动车违停时自动触发','{\"event_type\":\"ill_parking\",\"description\":\"机动车违章停车事件，系统通过视频识别技术发现机动车违停时自动触发\",\"event_params\":{\"location\":{\"type\":\"string\",\"description\":\"事件触发位置\"},\"plate_number\":{\"type\":\"string\",\"description\":\"违章机动车车牌号\"}}}');
